"""Small English dialog vocabulary, generated by the languages library.

Import through LanguagesLibrary. No window or input dependencies live here.
"""
from itertools import product

from languages.english import english_language
from tools.dictstores import DictList, DictLookup
from tools.indexing import DictTupleIndexing
from tools.inflections import tag_defaults

from .InflectionGeneration import InflectionGeneration
from .ListTreeLanguage import ListTreeLanguage

DEFAULTS = {**tag_defaults, 'script': 'latin', 'case': 'nominative',
            'aspect': 'simple', 'noun': 'man', 'role': 'agent',
            'motion': 'associated', 'subjectivity': 'subject'}
LANGUAGE = ListTreeLanguage(english_language.semantics, english_language.grammar,
                            DEFAULTS, english_language.substitutions)
VOCABULARY = {'I': 'personal', **dict.fromkeys(('ball', 'boy', 'girl', 'house'), 'noun'),
              **dict.fromkeys(('give', 'see', 'take', 'talk', 'walk'), 'verb'),
              **dict.fromkeys(('red', 'small'), 'adjective')}
ROLES = ({'subjectivity': 'subject', 'role': 'agent', 'motion': 'associated'},
         {'subjectivity': 'direct-object', 'role': 'patient', 'motion': 'associated'},
         {'subjectivity': 'adverbial', 'role': 'location', 'motion': 'acquired'})


def parts(tree):
    """Keep generated word types; discard tree structure and the empty marker."""
    if not isinstance(tree, list) or not tree:
        return ()
    if isinstance(tree[0], str) and tree[0] in ('n', 'v', 'adj', 'det', 'adposition'):
        return tuple((tree[0], word) for word in tree[1:]
                     if isinstance(word, str) and word and word != '∅')
    return tuple(part for node in tree if isinstance(node, list) for part in parts(node))


def build_catalog():
    catalog = {}
    for lexeme, kind in VOCABULARY.items():
        if kind in ('noun', 'personal'):
            people = (('1', 'singular', 'masculine'), ('2', 'singular', 'masculine'),
                      ('3', 'singular', 'masculine'), ('3', 'singular', 'feminine'),
                      ('3', 'singular', 'neuter'), ('1', 'plural', 'masculine'),
                      ('2', 'plural', 'masculine'), ('3', 'plural', 'masculine')) if kind == 'personal' else (
                          ('3', 'singular', 'masculine'), ('3', 'plural', 'masculine'))
            points = [{**DEFAULTS, **role, 'noun': 'man' if kind == 'personal' else lexeme,
                       'noun-form': 'personal' if kind == 'personal' else 'common',
                       'person': person, 'number': number, 'gender': gender, 'definiteness': definite}
                      for (person, number, gender), role, definite in product(
                          people, ROLES, ('definite',) if kind == 'personal' else ('definite', 'indefinite', 'adefinite'))
                      if kind == 'personal' or number == 'plural' or definite != 'adefinite']
            tree = ['np', ['adposition'], ['n', 'man' if kind == 'personal' else lexeme]]
        elif kind == 'verb':
            points = [{**DEFAULTS, 'verb': lexeme, 'person': person, 'number': number}
                      for person, number in product(('1', '2', '3'), ('singular', 'plural'))]
            tree = ['vp', ['v', lexeme]]
        else:
            points = [{**DEFAULTS, 'noun': lexeme}]
            tree = ['adj', lexeme]
        points = [english_language.semantics.augment(tags) for tags in points]
        indexing = DictTupleIndexing(tuple(sorted(points[0])))
        traversal = DictList(lexeme, indexing, points)
        inflections = DictLookup(lexeme, indexing)
        forms, generated = {}, {}
        def demonstrate(tags, templates):
            return LANGUAGE.map(['choice', tree], 'latin', semes={'choice': tags})
        for tags, trees in InflectionGeneration().generate([demonstrate], traversal):
            words = parts(trees[0])
            text = ' '.join(word for _, word in words)
            inflections[tags] = trees[0]
            forms.setdefault(text, []).append(tags)
            generated[text] = words
        canonical = next(iter(forms))
        # Verbs start with the unmarked form; personal nouns start with I.
        label_tree = LANGUAGE.map(['inventory', tree], 'latin',
                                  semes={'inventory': {**points[0], 'definiteness': 'adefinite'}})
        label = ' '.join(word for _, word in parts(label_tree))
        catalog[lexeme] = {'kind': kind, 'label': label, 'canonical': canonical,
                           'forms': {text: tuple(tags) for text, tags in forms.items()},
                           'parts': generated, 'inflections': inflections}
    return catalog


def sentence(phrases):
    return ' '.join(part[1] for phrase in phrases for part in phrase['parts'])


def validate(phrases, catalog):
    """Resolve homonyms against agreement and compare the library's word order.

The result is a language-agnostic command, or None. This prototype supports
present-tense affirmative statements with one verb and up to three noun phrases.
"""
    verbs = [p for p in phrases if catalog[p['lexeme']]['kind'] == 'verb']
    if len(verbs) != 1:
        return None
    verb = verbs[0]['lexeme']
    patterns = {'walk': (('subject', 'verb'), ('subject', 'verb', 'adverbial')),
                'talk': (('subject', 'verb', 'adverbial'),),
                'give': (('subject', 'verb', 'direct-object', 'adverbial'),),
                'see': (('subject', 'verb', 'direct-object'),),
                'take': (('subject', 'verb', 'direct-object'),)}
    for pattern in patterns[verb]:
        if len(pattern) != len(phrases):
            continue
        choices = []
        for role, phrase in zip(pattern, phrases):
            entry = catalog[phrase['lexeme']]
            if (role == 'verb') != (entry['kind'] == 'verb'):
                break
            choices.append([tags for tags in entry['forms'][phrase['form']]
                            if role == 'verb' or tags['subjectivity'] == role])
        else:
            for meaning in product(*choices):
                subject, conjugation = meaning[0], meaning[1]
                if any(subject[key] != conjugation[key] for key in ('person', 'number')):
                    continue
                semes, children = {}, []
                for i, (phrase, tags) in enumerate(zip(phrases, meaning)):
                    opcode = f'phrase-{i}'
                    semes[opcode] = tags
                    if catalog[phrase['lexeme']]['kind'] == 'verb':
                        node = ['vp', ['v', phrase['lexeme']]]
                    else:
                        adjectives = [['adj', part[2]] for part in phrase['parts'] if part[0] == 'adj']
                        node = ['np', ['adposition'], *adjectives, ['n', tags['noun']]]
                    children.append([opcode, node])
                # Language.map supplies the syntax that ListTreeLanguage intentionally omits.
                expected = english_language.map(['clause', *children], 'latin',
                                                semes={'clause': DEFAULTS, **semes})
                if ' '.join(expected.split()) == sentence(phrases):
                    return {'verb': verb, 'arguments': tuple(
                        {'role': role, 'lexeme': phrase['lexeme'], 'tags': dict(tags),
                         'adjectives': tuple(part[2] for part in phrase['parts'] if part[0] == 'adj')}
                        for role, phrase, tags in zip(pattern, phrases, meaning) if role != 'verb')}
    return None
